"use client";

import { useRef } from "react";
import { useGSAP } from "@gsap/react";
import gsap from "gsap";
import { ScrollTrigger } from "gsap/ScrollTrigger";

gsap.registerPlugin(useGSAP, ScrollTrigger);

export function ScrollProgress() {
  const barRef = useRef<HTMLDivElement>(null);

  useGSAP(() => {
    const bar = barRef.current;
    if (!bar) return;

    const setProgress = gsap.quickSetter(bar, "scaleX");

    const trigger = ScrollTrigger.create({
      start: 0,
      end: "max",
      onUpdate: (self) => {
        setProgress(self.progress);
      },
    });

    // Sincroniza el estado inicial si la página restaura el scroll.
    setProgress(trigger.progress);
  }, []);

  return (
    <div
      aria-hidden="true"
      className="pointer-events-none fixed inset-x-0 top-0 z-[100] h-1"
    >
      <div
        ref={barRef}
        className="h-full bg-current will-change-transform"
        style={{
          transform: "scaleX(0)",
          transformOrigin: "left center",
        }}
      />
    </div>
  );
}
```

Móntalo una sola vez dentro del `<body>` del layout raíz. Usa `scaleX` en vez de `width`, así la actualización de cada frame no provoca reflow.
